using System.Collections.ObjectModel; using System.Windows.Input; using DrawVerify.Core.Authorization; using DrawVerify.Core.Interfaces; using DrawVerify.Core.Models;
namespace DrawVerify.App.ViewModels;
public sealed class ReportTemplateConfigurationViewModel : TaskScreenViewModel
{
    private readonly IReportTemplateService _service; private readonly ISessionAuthenticationService _session; private readonly RoleAuthorization _authorization; private readonly ICentralizedLogger? _logger; private string _message=""; private string _errors="";
    public ObservableCollection<ReportTemplate> Templates { get; } = new(); public ReportTemplate? SelectedTemplate { get; set; }
    public bool CanEdit => _session.IsAuthenticated && _authorization.IsAllowed(_session.CurrentUser, RolePermission.ManageGlobalConfiguration);
    public string Message { get=>_message; private set { _message=value; RaisePropertyChanged(nameof(Message)); } } public string ValidationErrors { get=>_errors; private set { _errors=value; RaisePropertyChanged(nameof(ValidationErrors)); } }
    private readonly IReportTemplatePreviewService? _preview;
    private readonly IReportTemplateExchangeService? _exchange;
    public ICommand NewCommand { get; } public ICommand DuplicateCommand { get; } public ICommand SaveCommand { get; } public ICommand DefaultCommand { get; } public ICommand DeleteCommand { get; } public ICommand PreviewCommand { get; }
    public ReportTemplateConfigurationViewModel(IReportTemplateService service, ISessionAuthenticationService session, RoleAuthorization authorization, ICentralizedLogger? logger=null, IReportTemplatePreviewService? preview=null, IReportTemplateExchangeService? exchange=null) { _service=service; _session=session; _authorization=authorization; _logger=logger; _preview=preview; _exchange=exchange; NewCommand=new Command(async _=>await CreateAsync(), _=>CanEdit); DuplicateCommand=new Command(async _=>await DuplicateAsync(), _=>CanEdit && SelectedTemplate is not null); SaveCommand=new Command(async _=>await SaveAsync(), _=>CanEdit && SelectedTemplate is not null); DefaultCommand=new Command(async _=>await SetDefaultAsync(), _=>CanEdit && SelectedTemplate is not null); DeleteCommand=new Command(async _=>await DeleteAsync(), _=>CanEdit && SelectedTemplate is not null); PreviewCommand=new Command(async _=>await PreviewAsync(), _=>CanEdit && SelectedTemplate is not null && _preview is not null); _=LoadAsync(); }
    private async Task LoadAsync() { try { Templates.Clear(); foreach(var template in await _service.ListAsync()) Templates.Add(template); SelectedTemplate=Templates.FirstOrDefault(); RaisePropertyChanged(nameof(SelectedTemplate)); } catch(UnauthorizedAccessException ex){ Message="Report template access denied."; ValidationErrors=ex.Message; } catch(Exception ex){ _logger?.Log(ex,"Report template UI load","Unable to load report templates."); Message="Unable to load report templates."; ValidationErrors=ex.Message; } }
    private async Task CreateAsync(){ try { var item=await _service.CreateAsync("New report template",_session.CurrentUser!.UserId); Templates.Add(item); SelectedTemplate=item; Message="Template created."; } catch(Exception ex){ Handle(ex,"create"); } }
    private async Task DuplicateAsync(){ try { var item=await _service.DuplicateAsync(SelectedTemplate!.Id,SelectedTemplate.Name+" copy",_session.CurrentUser!.UserId); Templates.Add(item); SelectedTemplate=item; Message="Template duplicated."; } catch(Exception ex){ Handle(ex,"duplicate"); } }
    private async Task SaveAsync(){ try { SelectedTemplate=await _service.SaveAsync(SelectedTemplate!,SelectedTemplate!.Version,_session.CurrentUser!.UserId); Message="Template saved."; } catch(Exception ex){ Handle(ex,"save"); } }
    private async Task SetDefaultAsync(){ try { await _service.SetDefaultAsync(SelectedTemplate!.Id,_session.CurrentUser!.UserId); await LoadAsync(); Message="Organization default selected."; } catch(Exception ex){ Handle(ex,"set default"); } }
    private async Task DeleteAsync(){ try { await _service.DeleteAsync(SelectedTemplate!.Id,SelectedTemplate.Version,_session.CurrentUser!.UserId); await LoadAsync(); Message="Template deleted."; } catch(Exception ex){ Handle(ex,"delete"); } }
    private async Task PreviewAsync(){ try { if (!CanEdit || _preview is null || SelectedTemplate is null) throw new UnauthorizedAccessException("Only an authenticated Admin can preview report templates."); await _preview.PreviewAsync(SelectedTemplate); Message="Preview generated."; } catch(Exception ex){ Handle(ex,"preview"); } }
    private void Handle(Exception ex,string operation){ if(ex is UnauthorizedAccessException){Message="Report template access denied."; ValidationErrors=ex.Message;} else { _logger?.Log(ex,$"Report template UI {operation}","Report template operation failed."); Message=$"Unable to {operation} report template."; ValidationErrors=ex.Message; } }
    private sealed class Command(Func<object?,Task> execute, Predicate<object?> can):ICommand { public event EventHandler? CanExecuteChanged; public bool CanExecute(object? p)=>can(p); public async void Execute(object? p)=>await execute(p); }
}
